package com.aditya.fefo.service;
import com.aditya.fefo.domain.Product; import com.aditya.fefo.dto.ProductDtos.*; import com.aditya.fefo.exception.ApiException; import com.aditya.fefo.repository.ProductRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProductService {private final ProductRepository repo; public ProductService(ProductRepository r){repo=r;} public List<ProductResponse> list(){return repo.findAll().stream().map(this::map).toList();} public ProductResponse get(UUID id){return map(repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found")));} @Transactional public ProductResponse create(CreateProductRequest r){if(repo.findBySku(r.sku()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"SKU already exists");return map(repo.save(new Product(r.sku(),r.name(),r.description())));} private ProductResponse map(Product p){return new ProductResponse(p.getId(),p.getSku(),p.getName(),p.getDescription(),p.isActive());}}
